Here's how to handle each scenario with modern MSTest (3.9+/3.10+):

```csharp
[TestClass]
public sealed class PlatformSpecificTests
{
    private readonly TestContext _testContext;
    private string? _tempFile;

    public PlatformSpecificTests(TestContext testContext)
    {
        _testContext = testContext;
    }

    // 1. Windows-only: skipped on other OSes
    [TestMethod]
    [OSCondition(OperatingSystems.Windows)]
    public void Registry_ReadsExpectedValue()
    {
        using var key = Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\MyApp");
        Assert.IsNotNull(key);
    }

    // 2. Skip in CI: runs only locally
    [TestMethod]
    [CICondition(ConditionMode.Exclude)]
    public void GpuRendering_ProducesCorrectOutput()
    {
        var result = GpuRenderer.Render(scene);
        Assert.IsNotNull(result);
    }

    // 3. Flaky external API: retry up to 3 times
    [TestMethod]
    [Retry(3)]
    [Timeout(10000)]
    public async Task WeatherApi_ReturnsForecast()
    {
        var forecast = await _weatherClient.GetForecastAsync(
            _testContext.CancellationToken);
        Assert.IsNotNull(forecast);
    }

    // 4. Temp files: TestCleanup runs even on failure
    [TestMethod]
    public void Export_WritesValidFile()
    {
        _tempFile = Path.GetTempFileName();

        var exporter = new DataExporter();
        exporter.Export(_tempFile);

        Assert.IsNotEmpty(File.ReadAllText(_tempFile));
    }

    [TestCleanup]
    public void Cleanup()
    {
        if (_tempFile is not null && File.Exists(_tempFile))
        {
            File.Delete(_tempFile);
        }
    }
}
```

**Summary of attributes used:**

| Scenario | Attribute/Pattern |
|----------|-------------------|
| Windows-only | `[OSCondition(OperatingSystems.Windows)]` |
| Skip in CI | `[CICondition(ConditionMode.Exclude)]` |
| Flaky API | `[Retry(3)]` |
| Cleanup on failure | `[TestCleanup]` method |

`[Retry]` requires MSTest 3.9+, `[OSCondition]`/`[CICondition]` require 3.10+. `[TestCleanup]` always runs after each test regardless of pass/fail, making it ideal for resource cleanup.
